import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const n=JSON.parse('{"title":"安全边际","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-theme/安全边际.md","filePath":"05_quotes/by-theme/安全边际.md"}'),r={name:"05_quotes/by-theme/安全边际.md"};function u(i,e,q,s,_,c){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="安全边际" tabindex="-1">安全边际 <a class="header-anchor" href="#安全边际" aria-label="Permalink to &quot;安全边际&quot;">​</a></h1><blockquote><p>&quot;安全边际是投资的基石。永远不要为了追求最大化收益而牺牲安全边际。&quot;——巴菲特</p></blockquote><p>安全边际来自老师格雷厄姆，是巴菲特60年投资生涯一以贯之的纪律。</p><hr><h2 id="经典语录" tabindex="-1">经典语录 <a class="header-anchor" href="#经典语录" aria-label="Permalink to &quot;经典语录&quot;">​</a></h2><blockquote><p>&quot;投资的全部意义在于，在好公司以合理价格买入。但合理价格远低于内在价值时买入，就是安全边际。&quot;</p></blockquote><blockquote><p>&quot;我们坚持在有安全边际的情况下投资。当没有安全边际时，我们不会出手，不管市场怎么走。&quot;</p></blockquote><blockquote><p>&quot;安全边际不是要你等待完美时机，而是要在价格显著低于价值时果断行动。&quot;</p></blockquote><blockquote><p>&quot;如果你的分析是正确的，你就会获得安全边际。安全边际是你犯错的容错空间。&quot;</p></blockquote><blockquote><p>&quot;当别人都在冒险的时候，安全边际是你最好的朋友。&quot;——对应2008年金融危机</p></blockquote><hr><h2 id="出处年份" tabindex="-1">出处年份 <a class="header-anchor" href="#出处年份" aria-label="Permalink to &quot;出处年份&quot;">​</a></h2><h2 id="_1978年-·-1989年-·-1992年-·-2008年-·-2016年-·-2020年" tabindex="-1">1978年 · 1989年 · 1992年 · 2008年 · 2016年 · 2020年 <a class="header-anchor" href="#_1978年-·-1989年-·-1992年-·-2008年-·-2016年-·-2020年" aria-label="Permalink to &quot;1978年 · 1989年 · 1992年 · 2008年 · 2016年 · 2020年&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键出处年份：</p><ul><li><a href="/01_letters/1978年/翻译">/01_letters/1978年/翻译</a></li><li><a href="/01_letters/1989年/翻译">/01_letters/1989年/翻译</a></li><li><a href="/01_letters/1992年/翻译">/01_letters/1992年/翻译</a></li></ul>',16)])])}const p=t(r,[["render",u]]);export{n as __pageData,p as default};
